#[cfg(test)]mod storm65_sleep66_request_development_tests {
 use super::*;
 const OTHER:u32=0xf1234567;
 fn world()->World {let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();let f:serde_json::Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();w.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}w.learned_skills.clear();w.learned_skills.extend([65,66]);w.hp=Some([1,200]);w.mp=Some([1,200]);let mut a=w.own_actor().unwrap().clone();a.id=OTHER;a.x+=1;a.incarnation+=10;w.actors.insert(OTHER,a);w}
 #[test]fn both_spells_send_full_u32_actor_xy_and_keep_authority_unchanged(){for skill in [65,66]{let w=world();let before=serde_json::to_value(&w).unwrap();let a=&w.actors[&OTHER];let mut bytes=vec![20,8,(skill-65)as u8];bytes.extend(OTHER.to_le_bytes());bytes.extend(a.x.to_le_bytes());bytes.extend(a.y.to_le_bytes());assert_eq!(request(&w,skill,Some(OTHER)).unwrap(),bytes);assert_eq!(reuse_millis(skill),if skill==65{2000}else{1500});assert_eq!(serde_json::to_value(&w).unwrap(),before);}}
 #[test]fn ten_cell_boundary_does_not_accept_self_dead_absent_or_missing_target(){for skill in [65,66]{let mut w=world();let own=w.own_actor().unwrap().clone();w.actors.get_mut(&OTHER).unwrap().x=own.x+10;assert!(request(&w,skill,Some(OTHER)).is_ok());w.actors.get_mut(&OTHER).unwrap().x+=1;assert!(request(&w,skill,Some(OTHER)).is_err());w.actors.get_mut(&OTHER).unwrap().x=own.x+1;w.actors.get_mut(&OTHER).unwrap().dead=true;assert!(request(&w,skill,Some(OTHER)).is_err());assert!(request(&w,skill,Some(own.id)).is_err());assert!(request(&w,skill,None).is_err());assert!(request(&w,skill,Some(23)).is_err());}}
 #[test]fn native_selection_labels_and_owner_fences_keep_actor_intent(){for skill in [65,66]{let mut w=world();let mut m=super::super::native_skill_selection::Model::default();m.sync(7,&w,true);m.select(Some(skill)).unwrap();let target=super::super::native_skill_selection::Target::capture(&w,OTHER);assert_eq!(m.choice(7,&w,target).unwrap().target,Some(OTHER));assert!(m.choice(8,&w,target).is_err());assert!(m.rows().iter().find(|r|r.id==skill).unwrap().label.contains(if skill==65{"雷霆風暴"}else{"沉睡之霧"}));w.actors.get_mut(&OTHER).unwrap().incarnation+=1;assert!(m.choice(7,&w,target).is_err());}}
 #[test]fn positive_mp_book_life_and_server_control_required_without_material_prediction(){for skill in [65,66]{let mut w=world();assert!(request(&w,skill,Some(OTHER)).is_ok());w.mp=Some([0,200]);assert!(request(&w,skill,Some(OTHER)).is_err());w.mp=Some([1,200]);w.learned_skills.remove(&skill);assert!(request(&w,skill,Some(OTHER)).is_err());w.learned_skills.insert(skill);w.hp=Some([0,200]);assert!(request(&w,skill,Some(OTHER)).is_err());w.hp=Some([1,200]);w.accept(&[0x25,2]).unwrap();assert!(request(&w,skill,Some(OTHER)).is_err());}}
 #[test]fn sleep_visual_is_not_success_ack_or_local_thirty_two_second_status(){let mut w=world();let before=(w.hp,w.mp,w.movement_blocks.clone());let now=Instant::now();let p=Pending{since:now,casts:w.own_cast_packets,messages:w.message_count,generation:w.generation,incarnation:w.own_actor().unwrap().incarnation};let mut b=vec![0x37];b.extend(OTHER.to_le_bytes());b.extend(760_u16.to_le_bytes());w.accept(&b).unwrap();assert_eq!(p.observe(&w,now),Feedback::Pending);assert_eq!((w.hp,w.mp,w.movement_blocks.clone()),before);w.message_count+=1;w.last_skill_rejection=Some((w.message_count,280));assert_eq!(p.observe(&w,now),Feedback::Rejected(280));}
}
